template<typename T>
inline auto round_unit_exp2_5(T x) -> T
{
    const auto r = std::nearbyint(x);
    const auto f = x - r;
    auto q = T(0.0013390867351159438);
    q = q * f + T(0.009666373693207714);
    q = q * f + T(0.055503571042534054);
    q = q * f + T(0.2402234894094699);
    q = q * f + T(0.6931471880293425);
    const auto p = T(1) + f * q;
    return pow2i<T>(static_cast<ieee_int<T>>(r)) * p;
}
